(* [comment removed for export] *)
Lemma hz_sh2_ioc {HCEIL : HeapCeil} : forall m A, rw_cells asegs m A hz_sh2 -> rw_cells asegs m (A + 16) [CB 3 (poison_bytes 3 0)].
Proof.
  intros m A SH. unfold hz_sh2 in SH.
  apply (proj1 (rw_cells_app asegs m A [_; _; _; _; _] _)) in SH. destruct SH as [_ SH]. cbn [cells_size csize Nat.add] in SH.
  apply (proj1 (rw_cells_app asegs m _ [_] _)) in SH. destruct SH as [SH _].
  replace (A + Z.of_nat 16) with (A + 16) in SH by lia. exact SH.
Qed.

